% mathsmap-diagram-colours {"version":1,"kind":"graph","base":[],"semantic":[],"reference":"source page 21 question 10a; teacher page 55"}
\begin{tikzpicture}[x=0.8cm,y=0.8cm]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\draw[line width=0.25pt,step=1] (0,0) grid (8,5);
\draw[->,line width=0.5pt] (0,0)--(8.4,0) node[right] {$x$};
\draw[->,line width=0.5pt] (0,0)--(0,5.4) node[above] {$y$};
\foreach \x in {1,...,8}{\draw[line width=0.4pt] (\x,0.08)--(\x,-0.08);\node[below] at (\x,-0.08) {\special{dvisvgm:raw <g data-graph-text="tick">}$\x$\special{dvisvgm:raw </g>}};}
\foreach \y in {1,...,5}{\draw[line width=0.4pt] (0.08,\y)--(-0.08,\y);\node[left] at (-0.08,\y) {\special{dvisvgm:raw <g data-graph-text="tick">}$\y$\special{dvisvgm:raw </g>}};}
\node[below left] at (0,0) {\special{dvisvgm:raw <g data-graph-text="tick">}$0$\special{dvisvgm:raw </g>}};
\draw[line width=0.8pt] (3,1)--(7,1)--(7,4)--cycle;
\fill (3,1) circle (1.3pt) node[below left] {$A$};
\fill (7,1) circle (1.3pt) node[below right] {$B$};
\fill (7,4) circle (1.3pt) node[above] {$C$};
\end{tikzpicture}

% mathsmap-diagram-colours {"version":1,"kind":"graph","base":[],"semantic":[],"reference":"source page 21 question 10b; teacher page 55"}
\begin{tikzpicture}[x=0.8cm,y=0.8cm]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\draw[line width=0.25pt,step=1] (-8,-4) grid (8,5);
\draw[->,line width=0.5pt] (-8,0)--(8.5,0) node[right] {$x$};
\draw[->,line width=0.5pt] (0,-4)--(0,5.5) node[above] {$y$};
\foreach \x in {-7,...,-1,1,2,...,7}{\draw[line width=0.4pt] (\x,0.08)--(\x,-0.08);\node[below] at (\x,-0.08) {\special{dvisvgm:raw <g data-graph-text="tick">}$\x$\special{dvisvgm:raw </g>}};}
\foreach \y in {-3,-2,-1,1,2,3,4}{\draw[line width=0.4pt] (0.08,\y)--(-0.08,\y);\ifnum\y=-1 \node[below right] at (.08,\y) {\special{dvisvgm:raw <g data-graph-text="tick">}$\y$\special{dvisvgm:raw </g>}};\else \node[left] at (-0.08,\y) {\special{dvisvgm:raw <g data-graph-text="tick">}$\y$\special{dvisvgm:raw </g>}};\fi}
\node[above right,xshift=.8mm,yshift=.5mm] at (0,0) {\special{dvisvgm:raw <g data-graph-text="tick">}$0$\special{dvisvgm:raw </g>}};
\draw[line width=0.8pt] (3,1)--(7,1)--(7,4)--cycle;
\draw[dashed,line width=0.8pt] (3,-3)--(7,-3)--(7,0)--cycle;
\draw[line width=0.8pt] (-3,-3)--(-7,-3)--(-7,0)--cycle;
\fill (3,1) circle (1.3pt) node[above left] {$A$};
\fill (7,1) circle (1.3pt) node[right] {$B$};
\fill (7,4) circle (1.3pt) node[above] {$C$};
\fill (3,-3) circle (1.3pt) node[below] {$A'$};
\fill (7,-3) circle (1.3pt) node[below] {$B'$};
\fill (7,0) circle (1.3pt) node[above left] {$C'$};
\fill (-3,-3) circle (1.3pt) node[below] {$A''$};
\fill (-7,-3) circle (1.3pt) node[below] {$B''$};
\fill (-7,0) circle (1.3pt) node[above left] {$C''$};
\end{tikzpicture}
